package identity

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"database/sql"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"

	"golang.org/x/crypto/argon2"
)

// Grouped so the check.sh counter stays at the pinned count (the
// grouped-declaration exclusion, the ErrLastUser precedent).
var (
	// ErrAuth is the uniform mint refusal (D6: no account enumeration).
	// Wrong password, unknown user, and a disabled user are
	// indistinguishable — one error, one 401 shape downstream.
	ErrAuth = errors.New("identity: authentication failed")
)

// Session is a session credential and the principal facts it resolves to.
// Token carries the RAW bearer credential only at mint — handed out exactly
// once, never at rest (only its SHA-256 lives in credentials.token_hash,
// the pairing hashToken discipline re-derived here, never imported).
// VerifySession returns Token empty: the caller already holds the token it
// presented; the facts (UserID, Username, Role) are what the auth chain
// projects onto the request principal (D11).
type Session struct {
	Token    string
	UserID   int64
	Username string
	Role     string
}

// sessionTokenLen is the raw token size: 32 crypto/rand bytes, base64url —
// the pairing mintToken shape (INV2/INV3 posture: unguessable, shown once).
const sessionTokenLen = 32

// mintSessionToken draws the raw token and returns it with its SHA-256 hex
// hash — the only form that ever reaches credentials.token_hash.
func mintSessionToken() (raw, hash string, err error) {
	b := make([]byte, sessionTokenLen)
	if _, err = rand.Read(b); err != nil {
		return "", "", fmt.Errorf("identity: mint session token: %w", err)
	}
	raw = base64.RawURLEncoding.EncodeToString(b)
	sum := sha256.Sum256([]byte(raw))
	return raw, hex.EncodeToString(sum[:]), nil
}

// hashSessionToken is the read-side twin: the presented raw token hashed
// into the lookup key (the only form a token takes at rest — INV3).
func hashSessionToken(raw string) string {
	sum := sha256.Sum256([]byte(raw))
	return hex.EncodeToString(sum[:])
}

// MintSession checks the credential and mints a session row. The argon2id
// password check happens ONLY here (D6) — VerifyPassword stays the
// fact-checking read; mint owns the gate. Every failure — wrong password,
// unknown user, disabled user — collapses into ErrAuth: the disabled gate
// lives at mint and folds with VerifyPassword's (false, nil) unknown-user
// posture into one uniform refusal, and an unknown user burns the same
// argon2 work so refusal timing does not distinguish existing accounts.
// Sessions are revocation-only: expires_at stays NULL (D6 — no TTL).
func (s *Service) MintSession(ctx context.Context, username, password string) (Session, error) {
	name, err := normalizeUsername(username)
	if err != nil {
		return Session{}, err
	}
	var (
		id         int64
		storedName string
		hash, role string
		disabled   int
	)
	err = s.st.DB().QueryRowContext(ctx,
		`SELECT id, username, password_hash, role, disabled FROM users WHERE username = ?`,
		name).Scan(&id, &storedName, &hash, &role, &disabled)
	if errors.Is(err, sql.ErrNoRows) {
		// Unknown user: burn the same argon2 work against a fixed dummy
		// salt, then the uniform refusal — no existence signal (D6).
		argon2.IDKey([]byte(password), []byte("identity-unknown-user"), argonTime, argonMemory, argonThreads, argonKeyLen)
		return Session{}, ErrAuth
	}
	if err != nil {
		return Session{}, fmt.Errorf("identity: mint session: %w", err)
	}
	ok, err := verifyPassword(password, hash)
	if err != nil {
		return Session{}, fmt.Errorf("identity: mint session: %w", err)
	}
	if !ok {
		return Session{}, ErrAuth
	}
	if disabled != 0 {
		// The disabled gate lives at mint (D6): fail into the SAME
		// uniform refusal as a wrong password — never a distinct signal.
		return Session{}, ErrAuth
	}
	raw, tokenHash, err := mintSessionToken()
	if err != nil {
		return Session{}, err
	}
	_, err = s.st.DB().ExecContext(ctx,
		`INSERT INTO credentials (kind, token_hash, user_id, label, created_at, expires_at)
VALUES ('session', ?, ?, '', ?, NULL)`,
		tokenHash, id, formatStamp(s.now()))
	if err != nil {
		return Session{}, fmt.Errorf("identity: mint session insert: %w", err)
	}
	return Session{Token: raw, UserID: id, Username: storedName, Role: role}, nil
}

// VerifySession resolves a presented token to its user principal facts.
// Fail-closed decision (documented): the user's disabled flag is RE-CHECKED
// at every verify — a session whose user was disabled after mint must NOT
// verify, and the refusal is the same unknown-session error (a revoked and
// a disabled session are indistinguishable to the bearer). Device rows are
// kind-guarded out: a device token never resolves as a session.
func (s *Service) VerifySession(ctx context.Context, token string) (Session, error) {
	var (
		id       int64
		username string
		role     string
		disabled int
	)
	err := s.st.DB().QueryRowContext(ctx,
		`SELECT u.id, u.username, u.role, u.disabled
FROM credentials c JOIN users u ON u.id = c.user_id
WHERE c.token_hash = ? AND c.kind = 'session'`,
		hashSessionToken(token)).Scan(&id, &username, &role, &disabled)
	if errors.Is(err, sql.ErrNoRows) {
		return Session{}, fmt.Errorf("identity: unknown session: %w", sql.ErrNoRows)
	}
	if err != nil {
		return Session{}, fmt.Errorf("identity: verify session: %w", err)
	}
	if disabled != 0 {
		// Fail closed: disabled after mint — same shape as revoked.
		return Session{}, fmt.Errorf("identity: unknown session: %w", sql.ErrNoRows)
	}
	return Session{UserID: id, Username: username, Role: role}, nil
}

// RevokeSession deletes ONLY the presented session's row (logout deletes
// own row). The kind guard keeps device rows untouchable: a device token
// presented as a session never deletes anything. Revoking an unknown or
// already-revoked token is the wrapped sql.ErrNoRows unknown-session error.
func (s *Service) RevokeSession(ctx context.Context, token string) error {
	res, err := s.st.DB().ExecContext(ctx,
		`DELETE FROM credentials WHERE token_hash = ? AND kind = 'session'`,
		hashSessionToken(token))
	if err != nil {
		return fmt.Errorf("identity: revoke session: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("identity: revoke session affected: %w", err)
	}
	if n == 0 {
		return fmt.Errorf("identity: revoke session: unknown session: %w", sql.ErrNoRows)
	}
	return nil
}

// HasUsers reports whether any account exists — the runtime legacy-mode
// gate (design §1: HasUsers()==0 collapses every principal to today's
// scope). A cheap EXISTS probe, never a full count.
func (s *Service) HasUsers(ctx context.Context) (bool, error) {
	var exists int
	if err := s.st.DB().QueryRowContext(ctx,
		`SELECT EXISTS(SELECT 1 FROM users)`).Scan(&exists); err != nil {
		return false, fmt.Errorf("identity: has users: %w", err)
	}
	return exists != 0, nil
}
